// event dose.missed (contract v1.1): {dose_id, patient_first_name, bed, meds[], scheduled_at, nurse_chat_ids[], doctor_chat_id, doctor_email}
// The message names the bed and time only: no patient name or medication leaves the server.
// Demo routing: staff alerts go to every number in WARD_WHATSAPP_STAFF (comma-separated, country code first).
const staff = () => [...new Set(($env.WARD_WHATSAPP_STAFF || '').split(',').map(s => s.replace(/\D/g, '')).filter(Boolean))];
const out = [];
for (const item of $input.all()) {
  const d = item.json.data || {};
  const at = d.scheduled_at ? DateTime.fromISO(d.scheduled_at).setZone('Africa/Tunis').toFormat('HH:mm') : '?';
  const text = `Medora: missed dose, bed ${d.bed ?? '?'} (due ${at}). Open Medora.`;
  for (const to of staff()) out.push({ json: { to, text, dose_id: d.dose_id } });
}
return out;

const out = [];
for (const item of $input.all()) {
  const d = item.json.data || {};
  if (!d.doctor_email) continue;
  const at = d.scheduled_at ? DateTime.fromISO(d.scheduled_at).setZone('Africa/Tunis').toFormat('dd/LL HH:mm') : '?';
  out.push({ json: {
    to: d.doctor_email,
    subject: `Missed dose · Bed ${d.bed ?? '?'}`,
    text: `A dose due at ${at} at bed ${d.bed ?? '?'} was not taken within 30 minutes.
The ward nurses were notified on WhatsApp. Open Medora for details.

— Medora`,
  } });
}
return out;
